#include <stdio.h>
int main() {
    int i, s = 0;
    for (i = 1; i <= 10; i++) {
        if (i % 2 == 0) continue;
        if (i > 7) break;
        s += i;
    }
    printf("%d", s);
    return 0;
}

#include <stdio.h>
int f(int n) {
    if (n <= 1) return 1;
    return n * f(n - 2);
}
int main() {
    printf("%d", f(7));
    return 0;
}

#include <stdio.h>
int main() {
    int n = 2, c = 0;
    switch (n) {
        case 1: c += 1;
        case 2: c += 2;
        case 3: c += 3; break;
        default: c += 10;
    }
    printf("%d", c);
    return 0;
}

